\begin{document}
\pagestyle{empty} %% IMPORTANT
\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=outer north east,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	%axis equal,
	%grid = both,
	xmin = -2.5,
	xmax = 4.5,
	ymin = -4.5,
	ymax = 0.5,
	xtick = {0},
	extra x ticks={},
	ytick = {0},
	xticklabels = {,,},
	yticklabels = {,,},
	xlabel = $x$,
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={at={(ticklabel* cs:1.02)},anchor=west,},
	extra x tick style={xticklabel style={yshift=0.75ex, anchor=south}},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

	% Dotted
	\addplot [domain=0.1:6, samples=100,rustred, dotted,
		line width=0.75pt, opacity=0.5, smooth]{-4/\x};
	%\addlegendentry{$y=x^2-2x+1$}
\node[label={[label distance=-5mm,text depth=-1ex,  rustred, rotate=0]0:{\small{$\displaystyle x=-\frac{4}{y}$}}}, inner sep=1.5pt] at (axis cs:3.0, -0.4) {};

	\addplot [domain=-3:6, samples=100, deepskyblue, dotted,
		line width=0.75pt, opacity=0.5, smooth]{\x -5};
	%\addlegendentry{$y=x+1$}
\node[label={[label distance=-5mm,text depth=-1ex,  deepskyblue, rotate=0]0:{\small{$x=y +5$}}}, inner sep=1.5pt] at (axis cs:2.4, -3.3) {};

\addplot [domain=-10:10, samples=100, black, dashed,
		line width=0.7pt, smooth, variable=\y]({-0.5},{\y});


	% Solid
	\addplot [domain=1:4, samples=100, rustred, solid,
		line width=1.1pt, smooth]{-4/\x};
	\addplot [domain=1:4, samples=100, deepskyblue, solid,
		line width=1.1pt, smooth]{\x -5};

	\begin{scope}
		\addplot [name path=f, domain=1:4, samples=100, rustred, solid, draw=none, line width=1pt, smooth]{-4/\x};
		\addplot [name path=g, domain=1:4, samples=100, draw=none, line width=1pt, smooth]{\x -5};
	    \addplot[rustred!40!white, fill opacity=0.5] fill between [of=f and g];
    \end{scope}	

	% Ends
	\draw[ultra thin, dashed] (axis cs:0,-1) -- (axis cs:4,-1);	
	\node[left=-2pt] at (axis cs:0,-1) {\footnotesize $-1$}; 
%	\node[circle, draw=none, fill=black, inner sep=1pt] at (axis cs:0,-1) {};
	\draw[dashed, ultra thin] (axis cs:0,-4) -- (axis cs:1,-4);	
	\node[left=-2pt] at (axis cs:0,-4) {\footnotesize $-4$}; 
%	\node[circle, draw=none, fill=black, inner sep=1pt] at (axis cs:0,-4) {};

	% Rot
	\coordinate[] (O) at (axis cs:-0.5,-0.4);
	\draw[-, thin, black, dotted] (O) ++(60:4mm and 1.3mm) 
		arc (60:120:4mm and 1.3mm);
	\draw[->, thick, black, solid] (O) ++(60:4mm and 1.3mm) 
		arc (60:-240:4mm and 1.3mm);
	\node[left] at (axis cs:-0.5,-1.9) {$\displaystyle \color{black}x=-\frac{1}{2}$};

%	\node[right] at (axis cs:0,2) {\footnotesize $2$};
%	\node[right] at (axis cs:0,5) {\footnotesize $5$};

	% Arrows
	\draw[->, line width=1pt, solid] (axis cs:1.3,-2.5) -- (axis cs:2.9,-2.5);	
	\node[circle, draw=none, fill=rustred, inner sep=1.2pt] at (axis cs:1.6,-2.5) {};	
	\node[circle, draw=none, fill=deepskyblue, inner sep=1.2pt] at (axis cs:2.5,-2.5) {};

	\end{axis}
\end{tikzpicture}
\end{document}

