\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\begin{document}
\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

	\begin{axis}[
	legend cell align={left},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend pos=north west,
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = middle,
	axis x line = middle,
	axis equal,
	%grid = both,
	xmin = -1.3,
	xmax = 2.3,
	ymin = -0.3,
	ymax = 2.3,
	xtick = {1},
	ytick = {0},    
%	xticklabels = {,,},
	yticklabels = {,,},
	xlabel = {$x$},
	ylabel = {$y$},
	xlabel style={below right},
	ylabel style={above left},
	every axis x label/.style={
	at={(ticklabel* cs:1.02)},anchor=west,},
	every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
	]

% Dotted
\addplot [domain=-3:4, samples=100, rustred, dotted,line width=0.75pt, opacity=0.5,smooth]{\x^3};
\node[label={[label distance=-5mm,text depth=-1ex,  rustred, rotate=0]0:
{\small{$y=x^3$}}}, inner sep=1.5pt] at (axis cs:0.95, 2.4) {};

\addplot [domain=-3:4, samples=100,deepskyblue, dotted,line width=0.75pt, opacity=0.5,smooth]{(\x)^(1/2)};
\node[label={[label distance=-5mm,text depth=-1ex,  deepskyblue, rotate=0]0:
{\small{$y=\sqrt{x}$}}}, inner sep=1.5pt] at (axis cs:1.8,1.2) {};

\addplot [domain=-3:5, samples=100, black, dashed,
		line width=0.7pt,	smooth]{2};
\node[label={right:{\small{$y=2$}}}, inner sep=1.5pt] at (axis cs:-1, 2.15) {};


	% Solid
	\addplot [domain=0:1, samples=100, rustred, solid,
		line width=1.1pt,	smooth]{\x^3};
	\addplot [domain=0:1, samples=100, deepskyblue, solid,
		line width=1.1pt,	smooth]{\x^(1/2)};


	\begin{scope}
		\addplot [name path=f, domain=0:1, samples=100, rustred, solid,
			draw=none, line width=1pt,	smooth]{\x^3};
		\addplot [name path=g, domain=0:1, samples=100,
			draw=none, line width=1pt, smooth]{\x^(1/2)};
	    \addplot[rustred!40!white, fill opacity=0.5] fill between [of=f and g]; 
    \end{scope}	

\draw[draw=black, dashed, ultra thin] (axis cs:1,0) -- (axis cs:1,1);

	% Rot
	\coordinate[] (O) at (axis cs:2,2);
	\draw[-, thin, black, dotted] (O) ++(-30:1.3mm and 4 mm) 
		arc (-30:30:1.3mm and 4mm);
	\draw[->, thick, black, solid] (O) ++(30:1.3mm and 4 mm) 
		arc (30:330:1.3mm and 4mm);

% Arrows
\draw[<       -, line width=1pt, solid] (axis cs:0.5,{(0.5*0.5*0.5)-0.3}) -- (axis cs:0.5,{(0.5)^(0.5)+0.3});	
\node[circle, draw=none, fill=deepskyblue, inner sep=1.2pt] at (axis cs:0.5,{(0.5)^(0.5)}) {};	
\node[circle, draw=none, fill=rustred, inner sep=1.2pt] at (axis cs:0.5,0.5*0.5*0.5) {};

%Ends
\draw[draw=black, dashed, ultra thin] (axis cs:1,0) -- (axis cs:1,1);

\end{axis}
\end{tikzpicture}
\end{document}

