	\def\rotlabely{3.0}	% y-value of vertical line label

	\def\arrowadd{0.8}	% Amount arrow extends past dots

	\def\ftnlabel{x = \sqrt{7y^2+8}-2}	% top function label
	\def\ftncolor{deepskyblue}		% function color
	\def\labelx{2.1}		% top label x-value
	\def\labely{-0.5}		% top label y-value	

	\def\xstart{function(\ystart)};
	\def\xend{function(\yend)};
	\def\ymid{(\ystart+\yend)/2+0.5};
	\def\xmid{function(\ymid)};

	\begin{axis}[
	trig format plots=rad,
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend style={font=\footnotesize},
