	({function(\y)},{\y});

	% Solid
	\addplot [domain=\ystart:\yend, samples=200, color=\ftncolor, solid, line width=1.1pt, smooth, variable=\y]
	({function(\y)},{\y});

	% Label
	\node[label={[label distance=-5mm,text depth=-1ex,  color=\ftncolor, rotate=0]0:{\small{$\displaystyle \ftnlabel$}}}, inner sep=1.5pt] at (axis cs:{\labelx},{\labely}) {};

