		\addplot [name path=f, domain=\yend:\ystart, samples=100, draw=none, line width=1pt, smooth, variable=\y]
	({function(\y)},{\y});
		\addplot [name path=g, domain=\ystart:\yend, samples=100, draw=none, line width=1pt, smooth, variable=\y]
