	\draw[dashed, ultra thin] (axis cs:0,{\ystart}) -- (axis cs:{\xline},{\ystart});
	\draw[dashed, ultra thin] (axis cs:0,{\ystart}) -- (axis cs:{\xstart},{\ystart});
	\node[left] at (axis cs:0,{\yend+\labeladd}) {\footnotesize $\yend$};
	\draw[dashed, ultra thin] (axis cs:0,{\yend}) -- (axis cs:{\xline},{\yend});
	\draw[dashed, ultra thin] (axis cs:0,{\yend}) -- (axis cs:{\xend},{\yend});

